pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address target, uint256 value) public {
        // Bound value to avoid overflow/underflow issues
        value = bound(value, 0, address(this).balance);

        // Record depositsCount before
        uint256 before = c.depositsCount();

        // Attempt sendMoney
        (bool success, ) = address(c).call{value: 0}(abi.encodeWithSignature("sendMoney(address,uint256)", target, value));

        // Record depositsCount after
        uint256 after = c.depositsCount();

        // Rule: depositsCount increases by 1 if and only if the call succeeded
        assertTrue(success ? after == before + 1 : after == before);
    }
}

