pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address target, uint256 value) public {
        vm.assume(value <= address(c).balance);
        uint256 balanceBefore = address(c).balance;
        try c.sendMoney(target, value) {
            uint256 expectedWithdraw = balanceBefore - value;
            assertTrue(c.withdraw() == expectedWithdraw);
        } catch {
            // If sendMoney reverts, withdraw should remain unchanged
            assertTrue(c.withdraw() == balanceBefore);
        }
    }
}

