pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address target, uint256 amount) public {
        vm.assume(target != address(0) && target != address(c) && target != address(this));
        amount = bound(amount, 1, address(c).balance);

        uint256 ownerOldBalance = address(this).balance;

        (bool success, ) = address(c).call(abi.encodeWithSignature("sendMoney(address,uint256)", target, amount));

        uint256 ownerNewBalance = address(this).balance;

        if (success) {
            assertTrue(ownerNewBalance - ownerOldBalance == amount);
        } else {
            assertTrue(ownerNewBalance == ownerOldBalance);
        }
    }
}

