pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address target, uint256 value) public {
        vm.assume(target != address(0));
        vm.assume(value > 0 && value <= address(c).balance / 2);

        uint256 balanceBefore = address(c).balance;

        // Simulate a failing external call by making target a contract that reverts
        vm.etch(target, hex"00");

        c.sendMoney(target, value);

        uint256 balanceAfter = address(c).balance;

        // The reference contract does not revert on failure (i.e., keeps the money)
        // The buggy contract reverts on success, so it would revert here instead
        // We check that the balance decreased (money sent) — this will pass for P but fail for M
        assertTrue(balanceAfter == balanceBefore - value, "Balance should decrease on failed call");
    }
}

